{"objective": "Implemente ingestão idempotente de webhooks num módulo CommonJS para Node 24. O adaptador HTTP já existe. Exporte initialize(db) e ingest(db, {tenantId,eventId,payload}), síncronas, com db de node:sqlite. Todos os campos são strings validadas pelo adaptador. A tabela effects deve expor tenant_id, event_id e payload. A primeira entrega retorna accepted. A repetição do mesmo evento e payload retorna duplicate sem novo efeito. A mesma chave com payload diferente retorna conflict sem sobrescrever o original. A chave inclui o tenant. O efeito precisa ser persistente e uma falha de escrita deve permitir nova tentativa. Sem serviços ou dependências externas. Banco novo de laboratório.", "role": "tech_lead_review:1", "task": "Revise o código contra a tarefa. Responda {"verdict":"pass ou fail","evidence":"achados"}.", "context": {"code": ""use strict";

function initialize(db) {
  db.exec(`
    CREATE TABLE IF NOT EXISTS effects (
      tenant_id TEXT NOT NULL,
      event_id TEXT NOT NULL,
      payload TEXT NOT NULL,
      PRIMARY KEY (tenant_id, event_id)
    );
  `);
}

function ingest(db, { tenantId, eventId, payload }) {
  if (db.isTransaction) {
    throw new Error("ingest must run outside a transaction");
  }

  const result = db.prepare(`
    INSERT INTO effects (tenant_id, event_id, payload)
    VALUES (?, ?, ?)
    ON CONFLICT(tenant_id, event_id) DO NOTHING
  `).run(tenantId, eventId, payload);

  if (result.changes === 1 || result.changes === 1n) {
    return "accepted";
  }

  const existing = db.prepare(`
    SELECT payload FROM effects WHERE tenant_id = ? AND event_id = ?
  `).get(tenantId, eventId);

  if (!existing) {
    throw new Error("Existing effect not found after insert conflict");
  }

  return existing.payload === payload ? "duplicate" : "conflict";
}

module.exports = { initialize, ingest };
